<template>
  <div
    class="preview-pane back-white q-pa-sm"
    :class="isPDF === true ? 'pdf-box' : ''"
    v-if="showTestingPanel"
  >
    <div class="row">
      <q-input
        outlined
        dense
        label="Document Id..."
        v-model="document_id"
        class="width-320px"
      />
      <f-btn
        :label="$t('test')"
        @click="sendApiRequest()"
        class="margin-left-auto"
      />
    </div>
    <pre
      class="language-json mt-3"
      v-if="isJsonOrXml"
    ><code ref="highlightedCode" class="language-json">{{ formattedData }}</code></pre>
    <iframe
      :src="formattedData + '#navpanes=0'"
      width="100%"
      height="93.5%"
      v-if="isPDF"
      class="iframe-container"
    ></iframe>
  </div>
</template>

<script>
import { Prism } from 'src/utils/prism';
import 'vue-prism-editor/dist/prismeditor.min.css';
import { docXsltApiService } from 'src/services';
import { useDocXsltStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import beautify from 'js-beautify';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';

export default {
  mixins: [helperMixin],
  data() {
    return {
      document_id: '',
      isJsonOrXml: false,
      isPDF: false,
      formattedData: '',
      formatOptions: {
        indent_size: 4,
        indent_char: ' ',
        eol: '\n',
        end_with_newline: false,
        preserve_newlines: true,
        max_preserve_newlines: 2,
        indent_inner_html: true,
        wrap_line_length: 0,
        unformatted: [],
        extra_liners: [],
      },
    };
  },
  watch: {
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal['xslt_data'] !== oldVal['xslt_data']) {
          this.current_model = newVal;
        }
      },
    },
  },
  methods: {
    async sendApiRequest() {
      try {
        //Params for the API
        this.showLoading();
        const formData = new FormData();
        formData.append('attribute_id', this.$route.params.id);
        formData.append('doc_id', this.document_id);
        formData.append('attribute_value', this.current_model.xslt_data);

        const response = await docXsltApiService.getPreviewOutput(formData, {
          responseType: 'blob',
        });

        this.hideLoading();
        if (response.success === false) {
          throw response;
        }

        //Formatting according to the API response
        if (response.type === 'application/pdf') {
          const url = URL.createObjectURL(response);
          this.formattedData = url;
          this.isPDF = true;
        } else if (response.type === 'application/xml') {
          this.formattedData = await response.text();
          this.formattedData = beautify.html(this.formattedData, {
            ...this.formatOptions,
          });
          this.isJsonOrXml = true;
        } else if (
          response.type === 'application/json' ||
          response.type === 'text/json'
        ) {
          const text = await response.text();
          this.formattedData = beautify.js(text, {
            ...this.formatOptions,
          });
          this.isJsonOrXml = true;
          this.formattedData = this.formattedData.trimStart();
        }

        if (this.isJsonOrXml === true) {
          this.$nextTick(() => {
            Prism.highlightElement(this.$refs.highlightedCode);
          });
        }
      } catch (error) {
        if (error?.type === 'application/json') {
          const errorObj = JSON.parse(await error.text());
          const errorCode = String(errorObj?.error_code || errorObj?.message || 'error');
          notify.error(this.$t(errorCode.toLowerCase()));
        } else {
          const msg = ApiExceptions.getErrorMessage(error);
          notify.error(msg);
        }
      }
    },
  },
  setup() {
    const doc_xslt = useDocXsltStore();
    const { current_model, processing, showTestingPanel } =
      storeToRefs(doc_xslt);

    return {
      current_model,
      processing,
      showTestingPanel,
    };
  },
};
</script>

