<!--vbase-->
<template>
  <q-card flat bordered class="import-container white-back">
    <q-card-section>
      <div class="row">
        <span v-if="$route.query.attribute_name && $route.query.attribute_type">
          {{ $route.query.attribute_name }} ({{ $route.query.attribute_type }})
        </span>
        <q-space />
        <f-btn @click="formatCode" :label="$t('format_button')" />
        <f-btn
          v-if="current_model.is_draft"
          @click="saveRecord"
          :label="$t('save')"
          class="q-ml-sm"
        />
      </div>
    </q-card-section>
    <q-card-section class="row items-center q-pb-md editor-height">
      <editor :formatCode="is_format_code" @formatComplete="afterFormatted" />
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { notify } from 'src/components/notifications/notify';
import editor from 'src/pages/Settings/Components/XSLT/editor.vue';
// import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { useDocXsltStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {
    editor,
    // Loader,
  },
  watch: {
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },
  },
  data() {
    return {
      is_format_code: ref(false),
    };
  },
  methods: {
    formatCode() {
      this.is_format_code = true;
    },
    afterFormatted(value: any) {
      this.is_format_code = value;
    },
    async saveRecord() {
      try {
        this.processing = true;
        await this.updateExtractionAttributeValueDraft();
        notify.success(this.$t('MSG_SAVE'));
        this.processing = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        this.processing = false;
      }
    },
  },
  setup() {
    const xslt_store = useDocXsltStore();
    const { processing, current_model } = storeToRefs(xslt_store);
    const { updateExtractionAttributeValueDraft } = xslt_store;
    return {
      processing,
      updateExtractionAttributeValueDraft,
      current_model,
    };
  },
});
</script>

