<template>
  <div class="col-4 secondary-c-text text-h6">
    <div class="row justify-end q-mr-sm">
      <f-btn
        :label="$t('preview')"
        @click="showTestingPanel = !showTestingPanel"
      />
    </div>
  </div>
  <div class="row">
    <div class="col-3 q-pa-sm">
      <div class="q-ma-md">
        <q-select
          disable
          readonly
          outlined
          use-input
          hide-dropdown-icon
          v-model="current_model.doc_type"
          v-bind:options="doc_type_list"
          :label="$t('document_type')"
          @update:model-value="current_model['doc_type'] = ''"
          emit-value
          map-options
          dense
          class="back-white"
        >
        </q-select>
      </div>
      <div class="q-ma-md">
        <q-select
          disable
          readonly
          outlined
          use-input
          hide-dropdown-icon
          v-model="current_model.e_doc_type"
          v-bind:options="['EDI', 'BOD']"
          :label="$t('e_document_type')"
          @update:model-value="current_model['doc_type'] = ''"
          emit-value
          map-options
          dense
          class="back-white"
        >
        </q-select>
      </div>
      <div class="q-pa-md example-column-equal-width">
        <div class="column border-bdbdbd">
          <div class="col border-bdbdbd q-pa-sm q-mb-sm">
            <span class="text-weight-bold"> Version </span>
          </div>
          <div
            style="
              height: 400px;
              overflow-y: auto;
              overflow-x: hidden;
              border: 1px solid #ccc;
            "
          >
            <div
              class="col border-bdbdbd q-pa-sm cursor-pointer row"
              v-for="(version, index) in versions"
              :class="{ active: Number(index) === activeVersion }"
              :key="version.id"
            >
              <div class="col-8 row items-center" @click="chooseVersion(index)">
                <div class="col-12">
                  <span class="text-weight-bold">
                    {{ version.version }}
                    <q-badge
                      v-if="version.is_active == true"
                      rounded
                      class="q-pa-sm q-ml-sm"
                      color="positive"
                      :label="$t('active')"
                    />
                    <q-badge
                      v-else-if="version.is_approved == true"
                      rounded
                      class="q-pa-sm q-ml-sm"
                      color="positive"
                      :label="$t('approved')"
                    />
                    <q-badge
                      v-else
                      rounded
                      class="q-pa-sm q-ml-sm"
                      color="grey"
                      :label="$t('draft')"
                    />
                  </span>
                </div>
                <div class="col-12">
                  {{
                    formatDateAccordingToPreference(version.created_on)
                      ? formatDateAccordingToPreference(version.created_on)
                      : formatDateAccordingToPreference(
                          version.last_modified_on,
                        )
                  }}
                </div>
                <div class="col-12">
                  {{ version.first_name }} {{ version.last_name }}
                </div>
              </div>
              <div
                class="col-4 row justify-end items-center"
                v-if="version.is_active == true"
              >
                <q-icon
                  name="edite"
                  size="sm"
                  color="grey"
                  @click="createExtractionAttributeValuesDrafts(index)"
                />
              </div>
              <div
                class="col-4 row justify-end items-center"
                v-else-if="version.is_draft == true"
              >
                <q-icon
                  name="checked"
                  size="sm"
                  color="grey"
                  @click="activateExtractionAttributeValueDrafts(index)"
                />
                <q-icon
                  name="edite"
                  size="sm"
                  color="grey"
                  @click="createExtractionAttributeValuesDraftsFroms(index)"
                />
                <q-icon
                  v-if="versions.length > 1"
                  name="delete"
                  size="sm"
                  color="grey"
                  @click="openDeleteDialog(index)"
                />
              </div>
              <div class="col-4 row justify-end items-center" v-else>
                <q-icon
                  name="checked"
                  size="sm"
                  color="grey"
                  @click="activateExtractionAttributeValueDrafts(index)"
                />
                <q-icon
                  name="edite"
                  size="sm"
                  color="grey"
                  @click="createExtractionAttributeValuesDraftsFroms(index)"
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="q-pa-sm" :class="showTestingPanel ? 'col-4' : 'col-9'">
      <editor />
    </div>
    <div class="col-5 q-pa-sm" style="">
      <EDocPreview />
    </div>
  </div>
  <q-dialog v-model="confirmDeleteDialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteAttribute()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <div class="loading-component" v-if="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import dateUtils from 'src/utils/date';
import { ApiExceptions } from 'src/exceptions';
import helperMixin from 'src/mixins/helperMixin';
import { notify } from 'src/components/notifications/notify';
import EDocPreview from 'src/components/EDocPreviewComponent.vue';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { useDocXsltStore, useDropdownStore } from 'src/store/main';
import editor from 'src/pages/Settings/Components/XSLT/edit-create.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, dateUtils],
  components: {
    
    editor,
    EDocPreview,
  },
  data() {
    return {
      activeVersion: 0,
    };
  },
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      try {
        this.processing = true;
        this.current_model.doc_type = this.$route.params.doc_type;
        this.current_model.e_doc_type = this.$route.params.e_doc_type;
        this.params.attribute_id = this.$route.params.id.toString();
        this.current_model.attribute_id = this.$route.params.id.toString();
        await this.listVersion(this.$route.params.id.toString());
        this.checkInitVersionActive();
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        logError(error);
      } finally {
        this.processing = false;
      }
    },
    chooseVersion(version: any) {
      this.activeVersion = version;
      this.processing = true;
      this.current_model.attribute_id = this.versions[version].attribute_id;
      this.current_model.draft_id = this.versions[version].id;
      this.current_model.xslt_data = this.versions[version].value;
      this.current_model.is_active = this.versions[version].is_active;
      this.current_model.is_draft = this.versions[version].is_draft;
      this.isReadOnly = this.versions[version].is_active;
      setTimeout(() => {
        this.processing = false;
      }, 2000);
    },
    checkInitVersionActive() {
      if (this.versions[0]) {
        this.isReadOnly = this.versions[0].is_active;
      }
    },
    async createExtractionAttributeValuesDrafts(version: any) {
      try {
        this.processing = true;
        this.current_model.is_active = false;
        this.current_model.attribute_id = this.versions[version].attribute_id;
        this.current_model.xslt_data = this.versions[version].value;
        const sentAttributeId = this.current_model.attribute_id;
        const response = await this.createExtractionAttributeValuesDraft();
        // Copy-on-write: if the default was cloned into a custom attribute, the
        // returned id differs from the one we sent. Adopt it into the URL so
        // init() lists versions under the custom id and re-visits load it.
        const newAttributeId = response?.data?.attribute_id;
        if (newAttributeId && newAttributeId !== sentAttributeId) {
          await this.$router.replace({
            path: `/settings/manage-xslt/${this.$route.params.doc_type}/${newAttributeId}/${this.$route.params.e_doc_type}`,
            query: this.$route.query,
          });
        }
        notify.success(this.$t('draft_created'));
        this.init();
        this.processing = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        this.processing = false;
      }
    },
    async createExtractionAttributeValuesDraftsFroms(version: any) {
      try {
        this.processing = true;
        this.current_model.is_active = false;
        this.current_model.attribute_id = this.versions[version].attribute_id;
        this.current_model.draft_id = this.versions[version].id;
        this.current_model.xslt_data = this.versions[version].value;
        await this.createExtractionAttributeValuesDraftFrom();
        notify.success(this.$t('draft_created'));
        this.init();
        this.processing = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        this.processing = false;
      }
    },
    async activateExtractionAttributeValueDrafts(version: any) {
      try {
        this.processing = true;
        this.current_model.attribute_id = this.versions[version].attribute_id;
        this.current_model.draft_id = this.versions[version].id;
        logInfo(this.versions[version].id, 'draft id');

        await this.activateExtractionAttributeValueDraft();
        notify.success(this.$t('draft_activated'));
        await this.init();
        this.chooseVersion(version);
        this.processing = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        this.processing = false;
      }
    },
    openDeleteDialog(version: any) {
      this.current_model.attribute_id = this.versions[version].attribute_id;
      this.current_model.draft_id = this.versions[version].id;
      this.confirmDeleteDialog = true;
    },
    async deleteAttribute() {
      try {
        await this.deleteExtractionAttributeValueDrafts();
        this.init();
        notify.success(this.$t('draft_deleted'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
      }
    },
  },
  setup() {
    const { datePattern } = useSettingStore();
    const dropdown_store = useDropdownStore();
    const xslt_store = useDocXsltStore();
    const {
      current_model,
      versions,
      params,
      processing,
      confirmDeleteDialog,
      isReadOnly,
      showTestingPanel,
    } = storeToRefs(xslt_store);
    const {
      listVersion,
      createExtractionAttributeValuesDraft,
      activateExtractionAttributeValueDraft,
      deleteExtractionAttributeValueDrafts,
      createExtractionAttributeValuesDraftFrom,
    } = xslt_store;
    const { doc_type_list } = storeToRefs(dropdown_store);
    return {
      doc_type_list,
      current_model,
      listVersion,
      versions,
      params,
      processing,
      isReadOnly,
      createExtractionAttributeValuesDraft,
      activateExtractionAttributeValueDraft,
      confirmDeleteDialog,
      deleteExtractionAttributeValueDrafts,
      datePattern,
      createExtractionAttributeValuesDraftFrom,
      showTestingPanel,
    };
  },
});
</script>
<style scoped>
.active {
  background-color: #d9eff8;
}
body.body--dark .active {
  color: gray !important;
}
</style>
